begin;
create function pg_temp.check_employee(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'Employees: %',label;end if;end $$;
set local role service_role;
do $$
declare actor uuid:='00000000-0000-4000-8000-000000000020'; person uuid; youth private.employee_assignments; board private.employee_assignments; source jsonb; result jsonb; before_count int; trainer_path text; youth_path text; board_path text;
begin
 select id into person from public.social_people where slug='jerome-ernsberger';
 select * into youth from private.employee_assignments where person_id=person and group_key='youth' and role_label='Jugendleiter';
 select * into board from private.employee_assignments where person_id=person and group_key='board' and role_label='IT & Administration';
 perform pg_temp.check_employee(youth.id is not null and board.id is not null,'existing shared person imported for multiple roles');
 perform pg_temp.check_employee((select count(*)=4 from private.employee_assignments where group_key='executive'),'current executive board imported');
 perform pg_temp.check_employee(exists(select 1 from private.employee_assignments a join public.social_people p on p.id=a.person_id where a.group_key='youth' and p.display_name='Laila Goldhagen') and not exists(select 1 from private.employee_assignments a join public.social_people p on p.id=a.person_id where a.group_key='youth' and p.display_name='Sina Rauch'),'current website roster, not outdated archive');
 result:=public.employee_management_request(null,'{"action":"list"}');perform pg_temp.check_employee(result->>'status'='403','live rights required');
 trainer_path:=person::text||'/'||repeat('a',64)||'.png';youth_path:=person::text||'/'||repeat('b',64)||'.png';board_path:=person::text||'/'||repeat('c',64)||'.png';
 update private.trainer_profiles set photo_path=trainer_path where person_id=person;
 source:=private.employee_photo_source(person,'role-'||youth.id::text);
 perform pg_temp.check_employee(source->>'path'=trainer_path and (source->>'inherited')::boolean,'trainer upload inherited by youth role');
 result:=public.employee_management_request(actor,jsonb_build_object('action','save_photo','personId',person,'roleKey','role-'||youth.id::text,'version',youth.version,'photoPath',youth_path));
 perform pg_temp.check_employee(result->>'ok'='true','own youth picture saved');
 perform pg_temp.check_employee(private.employee_photo_source(person,'role-'||youth.id::text)->>'path'=youth_path and private.employee_photo_source(person,'role-'||board.id::text)->>'path'=youth_path,'new own photo inherited by other role');
 perform pg_temp.check_employee(private.employee_photo_source(person,'trainer')->>'path'=trainer_path,'own trainer picture protected');
 result:=public.employee_management_request(actor,jsonb_build_object('action','save_photo','personId',person,'roleKey','role-'||board.id::text,'version',board.version,'photoPath',board_path));
 perform pg_temp.check_employee(private.employee_photo_source(person,'role-'||board.id::text)->>'path'=board_path and private.employee_photo_source(person,'role-'||youth.id::text)->>'path'=youth_path,'two own role images stay separate');
 result:=public.employee_management_request(actor,jsonb_build_object('action','clear_photo','personId',person,'roleKey','role-'||board.id::text,'version',board.version));
 perform pg_temp.check_employee(result->>'status'='409','stale photo change rejected');
 result:=public.employee_management_request(actor,jsonb_build_object('action','clear_photo','personId',person,'roleKey','role-'||board.id::text,'version',board.version+1));
 perform pg_temp.check_employee(private.employee_photo_source(person,'role-'||board.id::text)->>'path'=youth_path,'removal returns to inheritance');
 result:=public.employee_management_request(actor,jsonb_build_object('action','authorize_photo','personId',gen_random_uuid(),'roleKey','role-'||youth.id::text,'version',youth.version+1));
 perform pg_temp.check_employee(result->>'status'='400','cannot assign another person image');
 select count(*) into before_count from public.social_people;
 result:=public.employee_management_request(actor,'{"action":"save_assignment","groupKey":"youth","roleLabel":"New","version":10,"firstName":"No","lastName":"SideEffect"}');
 perform pg_temp.check_employee(result->>'status'='409' and (select count(*)=before_count from public.social_people),'invalid new revision creates no orphan person');
 result:=public.employee_management_request(actor,'{"action":"save_assignment","groupKey":"youth","roleLabel":"New","version":0,"firstName":"Jérôme","lastName":"Ernsberger"}');
 perform pg_temp.check_employee(result->>'status'='409' and (select count(*)=before_count from public.social_people),'duplicate person rejected');
 result:=public.employee_management_request(actor,jsonb_build_object('action','remove_assignment','assignmentId',youth.id,'version',youth.version+1));
 perform pg_temp.check_employee(exists(select 1 from private.trainer_profiles where person_id=person) and exists(select 1 from private.employee_assignments where id=board.id and active),'role removal keeps shared person and other roles');
 perform pg_temp.check_employee(not exists(select 1 from jsonb_array_elements(public.website_employee_groups()->'assignments') a where a->>'id'=youth.id::text),'removed role omitted publicly');
end $$;
reset role;
select pg_temp.check_employee(not has_function_privilege('anon','public.employee_management_request(uuid,jsonb)','EXECUTE') and not has_table_privilege('authenticated','private.employee_role_photos','UPDATE'),'private writes not directly available');
rollback;
